async function hitStop(sec = 0.05) {
  timeScale = 0;         // 게임 시간 멈춤(충격 강조)
  await wait(sec);       // 실제 시간 기준 (게임 시간 아님 — 안 그러면 영영 멈춤)
  timeScale = 1;
}
