const easeOutQuad = (t) => 1 - (1 - t) * (1 - t);           // 기민·자연(등장)
const easeOutBack = (t) => 1 + 2.70158 * Math.pow(t-1, 3)   // 경쾌·탄력(오버슛)
                            + 1.70158 * Math.pow(t-1, 2);
// 선형(등속)은 기계적·싸구려 → 곡선이 생명감·성격을 준다
// 적재적소: UI 등장 easeOut · 획득/성공 easeOutBack · 큰 전환 easeInOut
